import React, { useRef } from 'react';

export interface ButtonProps {
  label: string;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  loading?: boolean;
  icon_leading?: string;
  onPressed?: () => void;
  onLongPressed?: () => void;
}

const Button: React.FC<ButtonProps> = ({
  label,
  variant = 'primary',
  size = 'md',
  disabled = false,
  loading = false,
  icon_leading,
  onPressed,
  onLongPressed,
}) => {
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressTriggered = useRef<boolean>(false);

  const isInteractive = !disabled && !loading;

  const handlePointerDown = () => {
    if (!isInteractive) return;
    longPressTriggered.current = false;
    longPressTimer.current = setTimeout(() => {
      longPressTriggered.current = true;
      if (onLongPressed) onLongPressed();
    }, 500);
  };

  const handlePointerUp = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  const handlePointerLeave = () => {
    if (longPressTimer.current) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  const handleClick = () => {
    if (!isInteractive) return;
    if (longPressTriggered.current) {
      longPressTriggered.current = false;
      return;
    }
    if (onPressed) onPressed();
  };

  const baseStyle: React.CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '0.5rem',
    cursor: isInteractive ? 'pointer' : 'not-allowed',
    opacity: disabled ? 0.5 : 1,
    padding: size === 'sm' ? '4px 8px' : size === 'lg' ? '12px 20px' : '8px 14px',
    fontSize: size === 'sm' ? 12 : size === 'lg' ? 18 : 14,
    border: variant === 'ghost' ? '1px solid transparent' : '1px solid #ccc',
    background:
      variant === 'primary' ? '#2563eb' : variant === 'secondary' ? '#e5e7eb' : 'transparent',
    color: variant === 'primary' ? '#fff' : '#111',
    borderRadius: 6,
    userSelect: 'none',
  };

  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || loading}
      aria-busy={loading}
      data-variant={variant}
      data-size={size}
      style={baseStyle}
      onClick={handleClick}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerLeave}
      onKeyDown={(e) => {
        if ((e.key === 'Enter' || e.key === ' ') && isInteractive) {
          e.preventDefault();
          if (onPressed) onPressed();
        }
      }}
    >
      {loading ? (
        <span aria-label="loading" role="status">
          ⏳
        </span>
      ) : (
        <>
          {icon_leading && <span aria-hidden="true" data-icon={icon_leading}>◆</span>}
          <span>{label}</span>
        </>
      )}
    </div>
  );
};

export default Button;
